<script setup lang="ts">const {settings,loadSettings}=usePublicContent();await loadSettings();const subjects=computed(()=>settings.value?.contactSubjects||[]);const form=reactive({name:'',email:'',phone:'',company:'',subject:subjects.value[0]||'',message:''});const pending=ref(false),done=ref(false),error=ref('');async function submit(){pending.value=true;error.value='';try{await $fetch('/api/public/contact',{method:'POST',body:form});done.value=true;Object.assign(form,{name:'',email:'',phone:'',company:'',subject:subjects.value[0]||'',message:''})}catch(e:any){error.value=e?.data?.message||'Não foi possível enviar. Tente novamente.'}finally{pending.value=false}}</script>
<template><form class="am-form" @submit.prevent="submit"><label>Nome *<input v-model="form.name" required autocomplete="name"></label><label>Email *<input v-model="form.email" type="email" required autocomplete="email"></label><label>Telefone<input v-model="form.phone" type="tel" autocomplete="tel"></label><label>Empresa<input v-model="form.company" autocomplete="organization"></label><label class="full">Assunto<select v-model="form.subject"><option v-for="subject in subjects" :key="subject">{{subject}}</option></select></label><label class="full">Mensagem *<textarea v-model="form.message" required></textarea></label><div class="full"><button class="am-btn" :disabled="pending">{{pending?'A enviar…':'Enviar mensagem'}}</button><p v-if="done" class="am-toast" role="status">Mensagem enviada. Obrigado pelo contacto.</p><p v-if="error" class="am-toast" role="alert">{{error}}</p></div></form></template>
